actions.script:
if (checkoutAttemptId && !(checkoutAttemptId ==~ /[A-Za-z0-9-]{16,100}/)) { checkoutRejection='Invalid checkout identity.'; return }
def current=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',current.sessionId).one()
ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',session.terminalId).forUpdate(true).one()
current=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
if (!checkoutAttemptId) return
def sale=checkoutSnapshot ? new groovy.json.JsonSlurper().parseText(checkoutSnapshot) : null
if (!(sale instanceof Map) || sale.version!=2 || sale.checkoutAttemptId!=checkoutAttemptId ||
    sale.sourceTransactionId!=transactionId || sale.sessionId!=current.sessionId || sale.terminalId!=session.terminalId ||
    sale.organizationPartyId!=access.organizationPartyId || sale.userId!=ec.user.userId) {
    checkoutRejection='The saved checkout identity does not match this bill.'; return
}
def prior=ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',access.organizationPartyId)
    .condition('checkoutAttemptId',checkoutAttemptId).one()
if (prior) {
    if (prior.sessionId!=current.sessionId || prior.transactionId!=current.transactionId) {
        checkoutRejection='This checkout identity belongs to another bill.'; return
    }
    if (prior.statusId=='PtCompleted') {
        checkoutRejection=ec.service.sync().name('zenith.pos.PosOfflineServices.assert#CheckoutReceipt')
            .parameters([transactionId:prior.transactionId,sale:sale,failOnMismatch:false]).call().mismatch
        if (!checkoutRejection) completedTransactionId=prior.transactionId
        return
    }
}
if (current.statusId!='PtCreated' || (current.checkoutAttemptId && current.checkoutAttemptId!=checkoutAttemptId)) {
    checkoutRejection='This bill has another checkout in progress. Reconnect to confirm its saved payment.'; return
}
def revision=ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',transactionId).call().revision
if (!sourceRevision || sourceRevision!=revision) {
    checkoutRejection='The bill changed before payment. Refresh it and confirm the current items and total.'; return
}
checkoutRejection=ec.service.sync().name('zenith.pos.PosOfflineServices.assert#CheckoutReceipt')
    .parameters([transactionId:transactionId,sale:sale,capturedDraft:true,failOnMismatch:false]).call().mismatch
// The transition records the identity only after successful completion, in this
// same locked transaction. A rejected preflight cannot strand the next attempt.

try {
def fail={ -> throw new IllegalArgumentException('The saved checkout details differ from its completed bill. The device copy was retained.') }
def txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
def decimal={ value -> new BigDecimal((value ?: 0).toString()).stripTrailingZeros().toPlainString() }
if (sale.total==null || sale.taxAmount==null || decimal(sale.total)!=decimal(txn.payableAmount) ||
    decimal(sale.taxAmount)!=decimal(txn.totalTaxAmount)) fail()
if (!capturedDraft && ((sale.paymentMethod=='Credit')!=(txn.isCredit=='Y') ||
    decimal(sale.change)!=decimal(txn.isCredit=='Y' ? 0 : txn.changeAmount))) fail()
def lines={ rows ->
    def grouped=[:]
    rows.each { row ->
        def key=groovy.json.JsonOutput.toJson([row.productId,row.mode ?: '',decimal(row.price),decimal(row.discount)])
        grouped[key]=(grouped[key] ?: 0G)+new BigDecimal(row.qty.toString())
    }
    grouped.collectEntries { key, qty -> [(key):decimal(qty)] }
}
def items=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).list()
if (lines(sale.items)!=lines(items.collect { [productId:it.productId,mode:it.salesModeId,price:it.unitPrice,discount:it.discountPercent,qty:it.quantity] })) fail()
if (capturedDraft) return
def reference={ value ->
    def text=(value ?: '').toString().trim(), prefix='OFFLINE:'+sale.offlineId
    text==prefix ? '' : text.startsWith(prefix+':') ? text.substring(prefix.length()+1) : text
}
def tenders={ rows -> rows.findAll { (it.amount as BigDecimal)!=0 }.groupBy { groovy.json.JsonOutput.toJson([it.method,reference(it.reference)]) }.collectEntries { method, payments ->
    [(method):decimal(payments.sum { new BigDecimal(it.amount.toString()) })]
} }
def payments=ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',transactionId).list()
    .findAll { txn.isCredit!='Y' || !txn.completedDate || it.paymentDate<=txn.completedDate }
if (tenders(sale.payments ?: [])!=tenders(payments.collect { [method:it.paymentMethod,amount:it.amount,reference:it.referenceNumber] })) fail()
if (sale.customer?.partyId && sale.customer.partyId!=txn.customerPartyId) fail()
if (sale.customer?.phone && sale.customer.phone.toString().replaceAll(/\D/,'')!=(txn.customerPhone ?: '').toString().replaceAll(/\D/,'')) fail()
if (sale.paymentMethod=='Credit' && sale.customer?.creditDays!=null && decimal(sale.customer.creditDays)!=decimal(txn.creditDays)) fail()
if (sale.paymentMethod=='Credit' && sale.customer?.termsReason?.toString()?.trim() &&
    sale.customer.termsReason.toString().trim()!=(txn.creditTermsReason ?: '').toString().trim()) fail()
} catch (IllegalArgumentException invalid) {
    if (failOnMismatch) throw invalid
    mismatch=invalid.message
}

def org=access.organizationPartyId
def discountSetting=kotWorkspace ? null : ec.entity.find('moqui.security.UserPreference').condition('userId',org).condition('preferenceKey','POS_DISC_LIMIT').one()?.preferenceValue
def terminal=ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).one()
def modes=offered.modes.collect { [id:it.salesModeId,name:it.modeName,inclusive:it.isTaxInclusive=='Y',disc:it.discountPercent ?: 0,source:it.priceSource] }
def rules=ec.entity.find('zenith.erp.pos.PosSalesModeOrgConfig').condition('organizationPartyId',org).list()
def productIds=catalog.products*.productId
def productRows=productIds ? ec.entity.find('mantle.product.Product').condition('productId','in',productIds).list().collectEntries { [(it.productId):it] } : [:]
def overridePrices=productIds ? ec.entity.find('zenith.erp.pos.PosProductModePrice')
    .condition('productId','in',productIds).list()
    .findAll { !it.organizationPartyId || it.organizationPartyId == org }
    .collectEntries { [(it.productId+'\u0000'+it.salesModeId):it.price] } : [:]
def region=terminal.stateCode ?: terminal.regionGeoId ?: ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId',org).limit(1).one()?.stateCode
def other=!kotWorkspace && region ? ec.entity.find('zenith.erp.india.IndiaState').condition('stateCode','not-equals',region).limit(1).one()?.stateCode : null
def interstate=other && productIds ? ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([organizationPartyId:org,
    items:productIds.collect { id -> def p=productRows[id];[productId:id,productTaxCode:p.productTaxCode,taxCategoryId:p.taxCategoryId,quantity:1,unitAmount:100,isTaxInclusive:'N'] },
    originRegionGeoId:region,destinationRegionGeoId:other,transactionType:'SALE']).call() : null
def products=catalog.products.withIndex().collect { product, index ->
    def p=productRows[product.productId]
    def prices=[:]
    modes.each { mode ->
        def override=overridePrices[p.productId+'\u0000'+mode.id]
        def price=override != null ? override : p.mrpAmount
        prices[mode.id]=[price:price,disc:override == null && mode.source in ['PpsDiscountMrp','PpsDiscountList'] ? mode.disc : 0,blocked:price==null]
    }
    product+[printName:p.printName ?: p.productName,prices:prices] +
        (kotWorkspace ? [amountUomId:p.amountUomId] :
            [interstateRates:interstate?.taxedItems ? (interstate.taxedItems[index].taxBreakdowns?.collect { it.taxRate ?: 0 } ?: []) : null])
}
def customerIds=ec.entity.find('mantle.party.Party').condition('ownerPartyId',org).list()*.partyId
def customers=[]
if (customerIds) ec.entity.find('mantle.party.PartyRole').condition('partyId','in',customerIds)
    .condition('roleTypeId','in',['Customer','CustomerBillTo']).list().unique { it.partyId }.each { role ->
    def detail=ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',role.partyId).limit(1).list()
    def person=detail ? detail[0] : null
    def name=person?.organizationName ?: [person?.firstName,person?.lastName].findAll { it }.join(' ')
    def phone=''
    ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId',role.partyId).conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list().each { link ->
        def tel=ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId',link.contactMechId).one()
        if (!phone && tel) phone=[tel.countryCode,tel.areaCode,tel.contactNumber].findAll { it }.join('')
    }
    if (!name) return
    def customer=[partyId:role.partyId,name:name,phone:phone]
    if (!kotWorkspace) {
        def party=ec.entity.find('mantle.party.Party').condition('partyId',role.partyId).one()
        def registration=ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',role.partyId).call()
        customer += [creditDays:party.creditDays,state:registration?.regionGeoId ?: '',gstin:registration?.registrationNumber ?: '']
    }
    customers.add(customer)
}
def templates=ec.entity.find('zenith.erp.pos.PosReceiptTemplate').condition('organizationPartyId',org).condition('printUse',null).condition('isActive','Y').orderBy('-isDefault,templateId').list()
def template=templates.find { it.facilityId==terminal.facilityId } ?: templates.find { !it.facilityId }
workspace=[version:2,userId:ec.user.userId,organizationPartyId:org,terminalId:terminalId,cachedAt:ec.user.nowTimestamp.time,
    products:products,customers:customers,modes:modes,canOverride:kotWorkspace || priceAccess?.canOverride==true,
    rules:rules.collect { [mode:it.salesModeId,customer:it.requireCustomer=='Y',minimum:it.minOrderAmount ?: 0] },
    discountLimit:discountSetting?.trim() ? new BigDecimal(discountSetting) : null,
    state:terminal.stateCode ?: terminal.regionGeoId ?: ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId',org).limit(1).one()?.stateCode,
    store:[name:template?.companyName ?: terminal.terminalName,taxReg:template?.taxRegistrationNumber ?: terminal.taxRegistrationNumber ?: '',
        address:template ? [template.addressLine1,template.addressLine2,template.city,template.state,template.pincode].findAll { it }.join(', ') : '',phone:template?.phone ?: '']]
if (!kotWorkspace) {
    workspace.creditTimeZone=ec.user.timeZone.ID
    workspace.canOverrideCreditTerms=ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')
    workspace.store += [email:template?.email ?: '',receiptWidth:template?.receiptWidth ?: '80mm',printLeftMargin:template?.printLeftMargin,
        printTopMargin:template?.printTopMargin,
        showLogo:template?.showLogo ?: 'N',logoUrl:template?.logoUrl ?: '',showTaxBreakdown:template?.showTaxBreakdown ?: 'Y',
        showDiscount:template?.showDiscount ?: 'Y',showCustomerInfo:template?.showCustomerInfo ?: 'Y',
        showPaymentDetails:template?.showPaymentDetails ?: 'N',showItemTax:template?.showItemTax ?: 'N',
        headerText:template?.headerText ?: '',footerText:template?.footerText ?: '',termsText:template?.termsText ?: '']
    workspace.creditReceiptText=[headerText:template?.creditHeaderText ?: workspace.store.headerText,
        footerText:template?.creditFooterText ?: workspace.store.footerText,termsText:template?.creditTermsText ?: workspace.store.termsText]
    workspace.receiptOptions=['normal','credit'].collectEntries { design ->
        [(design):ec.service.sync().name('zenith.pos.ReceiptTemplateServices.resolve#ReceiptOptions')
            .parameters([storedJson:template?.receiptOptionsJson,receiptDesign:design]).call().options]
    }
}

ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).forUpdate(true).one()
def original=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId)
    .condition('terminalId',terminalId).condition('organizationPartyId',access.organizationPartyId).forUpdate(true).one()
if (!original || !(original.statusId in ['PsOpen','PsClosed'])) throw new IllegalArgumentException('The original session is unavailable. Keep this saved sale for review.')
if (original.statusId=='PsClosed') {
    closedSession=[sessionId:sessionId,closeDate:original.closeDate,lastActivityDate:original.lastActivityDate]
    original.statusId='PsOpen'; original.update()
}

def org=access.organizationPartyId
def fail={ String message -> throw new IllegalArgumentException(message) }
def customerOnlyDraft=draftOnly && (sale.customer?.partyId || sale.customer?.name?.toString()?.trim())
if (sale.version!=2 || !sale.offlineId || sale.offlineId.toString().size()>120 || sale.terminalId!=terminalId || sale.organizationPartyId!=org || sale.userId!=ec.user.userId || !(sale.items instanceof List) ||
    (!sale.items && !(draftOnly && sale.sourceTransactionId) && !customerOnlyDraft) || sale.items.size()>1000 || !(sale.taxOn in ['Y','N'])) fail('Invalid offline sale identity or items.')
def issued=java.sql.Timestamp.from(java.time.Instant.parse(sale.ts as String))
if (issued.time>ec.user.nowTimestamp.time+300000L) fail('The terminal clock is ahead. Keep this sale for review.')
ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).forUpdate(true).one()
def keyScope=draftOnly ? [org,'draft',terminalId,sale.sessionId,ec.user.userId].join('\u0000')+'\u0000' : org+'\u0000'+(holdOnly ? 'held\u0000' : '')
def key=java.util.UUID.nameUUIDFromBytes((keyScope+sale.offlineId).getBytes('UTF-8')).toString()
def draftHash=draftOnly ? java.security.MessageDigest.getInstance('SHA-256').digest(groovy.json.JsonOutput.toJson(sale).getBytes('UTF-8')).encodeHex().toString() : null
if (holdOnly) {
    def held=ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('heldId',key).one()
    if (held) {
        if (held.sessionId!=sale.sessionId) fail('The held bill belongs to a different session.')
        if (held.statusId=='PhHeld') {
            def items=new groovy.json.JsonSlurper().parseText(held.itemsJson ?: '[]')
            def id=items ? items[0].sourceTransactionId : null
            heldSource=[serverHeldId:key,sourceHeldId:key,sourceTransactionId:id,
                sourceRevision:id ? ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',id).call().revision : null]
        }
        offlineId=sale.offlineId; return
    }
}
def prior=ec.entity.find('zenith.erp.pos.PosOfflineTransaction').condition('offlineTransactionId',key).one()
if (draftOnly && prior) {
    def receipt=new groovy.json.JsonSlurper().parseText(prior.transactionDataJson ?: '{}')
    def restored=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',prior.createdTransactionId).forUpdate(true).one()
    if (prior.statusId!='OtDraftRestored' || prior.terminalId!=terminalId || receipt.hash!=draftHash ||
        !restored || restored.sessionId!=sale.sessionId || restored.organizationPartyId!=org || restored.statusId!='PtCreated') { restoreConflict=true; return }
    def revision=ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',restored.transactionId).call().revision
    if (receipt.revision!=revision) { restoreConflict=true; return }
    offlineId=sale.offlineId; restoredTransactionId=restored.transactionId; return
}
if (prior?.statusId=='OtSynced') {
    if (sale.checkoutAttemptId) {
        def original=new groovy.json.JsonSlurper().parseText(prior.transactionDataJson ?: '{}')
        def canonical
        canonical={ value ->
            value instanceof Map ? value.collectEntries { k, v -> [(k):canonical(v)] } :
                value instanceof List ? value.collect { canonical(it) } :
                value instanceof Number ? new BigDecimal(value.toString()).stripTrailingZeros().toPlainString() : value
        }
        def fields=['version','offlineId','checkoutAttemptId','userId','organizationPartyId','terminalId','sessionId',
            'sourceTransactionId','sourceRevision','items','customer','mode','taxOn','total','taxAmount','paymentMethod','payments','change']
        if (prior.terminalId!=terminalId || canonical(original.subMap(fields))!=canonical(sale.subMap(fields)))
            fail('This saved checkout identity was already used for different bill details.')
    }
    offlineId=sale.offlineId; return
}
if (!holdOnly && !draftOnly) {
    if (sale.checkoutAttemptId && !(sale.checkoutAttemptId ==~ /[A-Za-z0-9-]{16,100}/)) fail('Invalid checkout identity.')
    def completed=sale.checkoutAttemptId ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org)
        .condition('checkoutAttemptId',sale.checkoutAttemptId).forUpdate(true).one() : null
    // Older importers wrote the exact offline receipt ID into tender references.
    // This is also proof of a committed sale; equal amounts alone are never proof.
    if (!completed && sale.sourceTransactionId) {
        def prefix='OFFLINE:'+sale.offlineId
        def references=ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',sale.sourceTransactionId).list()
            .findAll { it.referenceNumber==prefix || it.referenceNumber?.startsWith(prefix+':') }
        if (references) completed=ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org)
            .condition('transactionId',sale.sourceTransactionId).forUpdate(true).one()
    }
    if (completed?.statusId=='PtCompleted') {
        if (completed.sessionId!=sale.sessionId || completed.transactionId!=sale.sourceTransactionId)
            fail('This checkout identity belongs to another bill. The saved sale was retained.')
        def permission=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',completed.transactionId).call()
        if (!permission?.allowed) return
        ec.service.sync().name('zenith.pos.PosOfflineServices.assert#CheckoutReceipt')
            .parameters([transactionId:completed.transactionId,sale:sale]).call()
        if (ec.message.hasError()) return
        ec.service.sync().name('create#zenith.erp.pos.PosOfflineTransaction').parameters([offlineTransactionId:key,terminalId:terminalId,
            offlineTimestamp:issued,syncedTimestamp:ec.user.nowTimestamp,transactionDataJson:groovy.json.JsonOutput.toJson(sale),
            itemCount:sale.items.size(),grandTotal:sale.total,paymentMethod:sale.paymentMethod,statusId:'OtSynced',syncAttempts:1,
            createdTransactionId:completed.transactionId]).call()
        if (!ec.message.hasError()) offlineId=sale.offlineId
        return
    }
}
if (!holdOnly && !draftOnly && sale.checkoutReconcileOnly==true)
    fail('The original payment response could not be confirmed. The saved sale was retained without applying another payment.')
def recovery=draftOnly ? [closedSession:false] : ec.service.sync().name('zenith.pos.PosOfflineServices.prepare#OfflineSession').parameters([terminalId:terminalId,sessionId:sale.sessionId]).call()
if (ec.message.hasError()) return
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sale.sessionId).forUpdate(draftOnly).one()
if (draftOnly && (!session || session.statusId!='PsOpen' || session.terminalId!=terminalId || session.organizationPartyId!=org)) fail('The original counter session is closed. The draft is still saved on this device.')
def transactionId
def keepCapturedSource=false
def sourceHeld
if (sale.sourceHeldId) {
    sourceHeld=ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('heldId',sale.sourceHeldId).forUpdate(true).one()
    def heldItems=sourceHeld ? new groovy.json.JsonSlurper().parseText(sourceHeld.itemsJson ?: '[]') : []
    if (!sourceHeld || sourceHeld.sessionId!=sale.sessionId || sourceHeld.statusId!='PhHeld' ||
        !sale.sourceTransactionId || !heldItems || heldItems[0].sourceTransactionId!=sale.sourceTransactionId)
        fail('This held bill was already recalled or changed. The device copy remains saved for review.')
}
if (sale.sourceTransactionId) {
    def source=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',sale.sourceTransactionId).forUpdate(true).one()
    if (source) {
        def permission=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameters([transactionId:source.transactionId]).call()
        if (!permission?.allowed) return
        if (source.sessionId!=session.sessionId || source.transactionNumber || (source.paidAmount ?: 0)!=0 ||
            ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',source.transactionId).count()>0 ||
            ec.entity.find('zenith.erp.pos.PosQrPayment').condition('transactionId',source.transactionId).count()>0) fail('The original draft changed or has a tender in progress. Keep this offline sale for review; it was not imported twice.')
        // Closing a drawer can discard its unpaid draft. Preserve the voided record and
        // recover the complete local snapshot into a new bill, retaining its source in the ledger.
        if (!(recovery.closedSession && source.statusId=='PtVoided')) {
            def revision=ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',source.transactionId).call().revision
            def unchanged=source.statusId==(sourceHeld ? 'PtHeld' : 'PtCreated') && sale.sourceRevision && sale.sourceRevision==revision
            if (!unchanged && (holdOnly || draftOnly || sourceHeld || !(source.statusId in ['PtCreated','PtVoided'])))
                fail('The original draft changed. Keep this offline sale for review; its saved draft was not overwritten.')
            // A completed local receipt is independent of a changed, untendered draft.
            // Preserve that server draft and replay the full collected receipt into a new bill.
            if (unchanged) {
                transactionId=source.transactionId
                if (sourceHeld) { source.statusId='PtCreated'; source.update() }
                keepCapturedSource=!holdOnly && !draftOnly && sale.checkoutWasOnline==true && sale.checkoutAttemptId
                if (keepCapturedSource) {
                    ec.service.sync().name('zenith.pos.PosOfflineServices.assert#CheckoutReceipt')
                        .parameters([transactionId:transactionId,sale:sale,capturedDraft:true]).call()
                    if (ec.message.hasError()) return
                } else {
                    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).list().each { item ->
                        ec.service.sync().name('zenith.pos.PosServices.remove#PosTransactionItem').parameters([transactionId:transactionId,itemSeqId:item.itemSeqId]).call()
                    }
                }
            }
        }
    } else if (!recovery.closedSession) {
        fail('The original draft is unavailable. Keep this offline sale for review.')
    }
}
if (!transactionId) {
    if (draftOnly && ec.entity.find('zenith.erp.pos.PosTransaction').condition('sessionId',session.sessionId).condition('statusId','PtCreated').count())
        fail('There is already an open server cart. The device draft is still saved for review.')
    transactionId=ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction').parameters([sessionId:session.sessionId,reuseOpenCart:false]).call().transactionId
}
if (ec.message.hasError()) return
if (!transactionId) fail('The saved bill could not be created. It remains on the device for retry.')
def txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
if (!holdOnly && !draftOnly && sale.checkoutAttemptId) {
    if (txn.checkoutAttemptId && txn.checkoutAttemptId!=sale.checkoutAttemptId) fail('This bill has another checkout in progress.')
    txn.set('checkoutAttemptId',sale.checkoutAttemptId)
}
def registration=sale.customer?.partyId ? ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',sale.customer.partyId).call() : null
def canonical=sale.customer?.partyId ? ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',sale.customer.partyId).limit(1).list() : []
def customerName=canonical ? (canonical[0].organizationName ?: [canonical[0].firstName,canonical[0].lastName].findAll { it }.join(' ')) : sale.customer?.name
if (!keepCapturedSource) txn.setAll([customerPartyId:sale.customer?.partyId,customerName:customerName,customerPhone:sale.customer?.phone,salesModeId:sale.mode ?: null,
    customerTaxRegNumber:registration?.registrationNumber,destinationRegionGeoId:registration?.regionGeoId ?: txn.originRegionGeoId])
if (!draftOnly) txn.set('entryDate',issued)
txn.update()
def priceAccess=ec.service.sync().name('zenith.pos.PosPriceServices.get#PriceOverrideAccess').call()
def discountSetting=ec.entity.find('moqui.security.UserPreference').condition('userId',org).condition('preferenceKey','POS_DISC_LIMIT').one()?.preferenceValue
def discountLimit=discountSetting?.trim() ? new BigDecimal(discountSetting) : null
if (!keepCapturedSource) {
sale.items.each { item ->
    if (!(item instanceof Map) || item.qty==null || item.price==null || (item.qty as BigDecimal)<=0 ||
        ((holdOnly || draftOnly) ? (item.price as BigDecimal)<0 : (item.price as BigDecimal)<=0)) fail('Positive prices and quantities are required offline; free items need online manager approval.')
    ec.service.sync().name('zenith.pos.PosModeServices.assert#TerminalMode').parameters([terminalId:terminalId,salesModeId:item.mode]).call()
    def resolved=ec.service.sync().name('zenith.pos.PosServices.resolve#PosModePrice').parameters([productId:item.productId,salesModeId:item.mode]).call()
    if (!priceAccess.canOverride && (resolved.blocked || (resolved.unitPrice as BigDecimal).compareTo(item.price as BigDecimal)!=0)) fail('POS write permission is required for this offline price override.')
    def percent=(item.discount ?: 0) as BigDecimal
    if (percent<0 || percent>100 || (percent!=(resolved.discountPercent ?: 0) && discountLimit!=null && percent>discountLimit)) fail('This discount needs online manager approval.')
    def added=ec.service.sync().name('zenith.pos.PosServices.add#PosTransactionItem').parameters([transactionId:transactionId,productId:item.productId,quantity:item.qty,unitPrice:item.price,salesModeId:item.mode,taxOn:sale.taxOn]).call()
    if (added?.itemSeqId) {
        def recorded=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).condition('itemSeqId',added.itemSeqId).one()
        // The normal add path treats an MRP-valued input as a default mode price.
        // Restore an explicitly captured offline override through the audited permission check.
        if ((recorded.unitPrice as BigDecimal).compareTo(item.price as BigDecimal)!=0)
            ec.service.sync().name('zenith.pos.PosPriceServices.set#ItemPrice').parameters([transactionId:transactionId,itemSeqId:added.itemSeqId,newPrice:item.price,taxOn:sale.taxOn]).call()
    }
    if (added?.itemSeqId && percent!=(resolved.discountPercent ?: 0)) ec.service.sync().name('update#zenith.erp.pos.PosTransactionItem').parameters([transactionId:transactionId,itemSeqId:added.itemSeqId,discountPercent:percent,discountAmount:(item.price as BigDecimal)*(item.qty as BigDecimal)*percent/100]).call()
}
if (ec.message.hasError()) return
ec.service.sync().name('zenith.pos.PosServices.refresh#PosTransactionTax').parameters([transactionId:transactionId,taxOn:sale.taxOn]).call()
txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
if (sale.roundOff!=null && ((sale.roundOff as BigDecimal).compareTo((txn.roundOff ?: 0) as BigDecimal)!=0)) {
    def step=ec.entity.find('moqui.security.UserPreference').condition('userId',org).condition('preferenceKey','POS_DISC_ROUNDSTEP').one()?.preferenceValue
    def roundStep=step?.trim() ? new BigDecimal(step) : 0G
    if (roundStep>0) {
        def rounded=(txn.grandTotal as BigDecimal).divide(roundStep,0,java.math.RoundingMode.FLOOR)*roundStep
        if ((sale.total as BigDecimal).compareTo(rounded)==0 && (sale.roundOff as BigDecimal).compareTo(rounded-(txn.grandTotal as BigDecimal))==0) {
            txn.setAll([payableAmount:rounded,roundOff:sale.roundOff]); txn.update()
        }
    }
}
}
if (sale.total==null || (sale.total as BigDecimal).compareTo(txn.payableAmount as BigDecimal)!=0 || sale.taxAmount==null || (sale.taxAmount as BigDecimal).compareTo(txn.totalTaxAmount as BigDecimal)!=0) fail('Offline tax or total differs from current rules. Sale retained for review, without changing its collected amount.')
if (sourceHeld) { sourceHeld.statusId='PhRecalled'; sourceHeld.recallTime=ec.user.nowTimestamp; sourceHeld.update() }
if (draftOnly) {
    def revision=ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',transactionId).call().revision
    ec.service.sync().name('create#zenith.erp.pos.PosOfflineTransaction').parameters([offlineTransactionId:key,terminalId:terminalId,
        offlineTimestamp:issued,syncedTimestamp:ec.user.nowTimestamp,statusId:'OtDraftRestored',createdTransactionId:transactionId,
        transactionDataJson:groovy.json.JsonOutput.toJson([hash:draftHash,revision:revision])]).call()
    if (!ec.message.hasError()) { offlineId=sale.offlineId; restoredTransactionId=transactionId }
    return
}
if (holdOnly) {
    def held=ec.service.sync().name('zenith.pos.PosServices.hold#Transaction')
        .parameters([transactionId:transactionId,heldId:key]).call()
    if (!ec.message.hasError() && held.heldId) {
        def record=ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('heldId',held.heldId).one()
        record.set('holdTime',issued).update()
        heldSource=[serverHeldId:key,sourceHeldId:key,sourceTransactionId:transactionId,
            sourceRevision:ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',transactionId).call().revision]
        offlineId=sale.offlineId
    }
    return
}
if (sale.paymentMethod=='Credit') {
    if (!sale.customer?.name || !sale.customer?.phone) fail('Credit requires a customer name and phone.')
    def payments=sale.payments == null ? [] : sale.payments
    if (!(payments instanceof List) || payments.size()>1 || ((sale.change ?: 0) as BigDecimal)!=0) fail('Enter a valid upfront credit payment.')
    def upfront=payments ? payments[0] : null
    if (payments && (!(upfront instanceof Map) || upfront.amount==null || (upfront.amount as BigDecimal)<=0 ||
        (upfront.amount as BigDecimal).scale()>2 || !(upfront.method in ['Cash','Card','UPI']))) fail('Enter a valid upfront credit payment.')
    ec.service.sync().name('zenith.pos.PosServices.complete#PosTransactionCredit').parameters([
        transactionId:transactionId,customerPartyId:sale.customer.partyId,customerName:sale.customer.name,
        customerPhone:sale.customer.phone,creditDays:sale.customer.creditDays,termsReason:sale.customer.termsReason,
        upfrontAmount:upfront?.amount,upfrontMethod:upfront?.method,attachMissingCustomerPhone:true]).call()
    if (!ec.message.hasError()) {
        def credit=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
        if (credit.creditDays!=null) {credit.creditDueDate=java.sql.Date.valueOf(issued.toInstant().atZone(ec.user.timeZone.toZoneId()).toLocalDate().plusDays(credit.creditDays as long));credit.update()}
        if (upfront) ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',transactionId).list().each { payment ->
            ec.service.sync().name('update#zenith.erp.pos.PosPayment').parameters([paymentId:payment.paymentId,
                paymentDate:issued,referenceNumber:'OFFLINE:'+sale.offlineId]).call()
        }
    }
} else {
    if (!(sale.payments instanceof List) || !sale.payments || sale.payments.size()>3) fail('Enter a valid payment breakdown.')
    def paid=0G
    sale.payments.each { payment ->
        if (!(payment.method in ['Cash','Card','UPI']) || payment.amount==null || (payment.amount as BigDecimal)<0 ||
            ((payment.amount as BigDecimal)==0 && !(keepCapturedSource && (txn.payableAmount as BigDecimal)==0)) ||
            (payment.amount as BigDecimal).scale()>2) fail('Invalid offline payment.')
        paid+=payment.amount as BigDecimal
    }
    def change=(sale.change ?: 0) as BigDecimal
    if (change<0 || (paid-change).compareTo(txn.payableAmount as BigDecimal)!=0 ||
        (change>0 && (sale.paymentMethod!='Cash' || sale.payments.size()!=1 || sale.payments[0].method!='Cash'))) fail('Payment breakdown or change does not match the sale.')
    sale.payments.each { payment ->
        def reference=(payment.reference ?: '').toString().trim().take(80)
        def received=ec.service.sync().name('zenith.pos.PosServices.process#PosPayment').parameters([transactionId:transactionId,paymentMethod:payment.method,amount:payment.amount,referenceNumber:'OFFLINE:'+sale.offlineId+(reference ? ':'+reference : '')]).call()
        if (!ec.message.hasError() && received?.paymentId) ec.service.sync().name('update#zenith.erp.pos.PosPayment').parameters([paymentId:received.paymentId,paymentDate:issued]).call()
    }
    if (ec.message.hasError()) return
    ec.service.sync().name('zenith.pos.PosServices.complete#PosTransaction').parameters([transactionId:transactionId]).call()
}
if (ec.message.hasError()) return
ec.service.sync().name('update#zenith.erp.pos.PosTransaction').parameters([transactionId:transactionId,completedDate:issued]).call()
ec.service.sync().name('create#zenith.erp.pos.PosOfflineTransaction').parameters([offlineTransactionId:key,terminalId:terminalId,offlineTimestamp:issued,syncedTimestamp:ec.user.nowTimestamp,transactionDataJson:groovy.json.JsonOutput.toJson(sale),itemCount:sale.items.size(),grandTotal:sale.total,paymentMethod:sale.paymentMethod,statusId:'OtSynced',syncAttempts:1,createdTransactionId:transactionId]).call()
if (!ec.message.hasError()) ec.service.sync().name('zenith.pos.PosOfflineServices.restore#OfflineSession').parameter('closedSession',recovery.closedSession).call()
if (!ec.message.hasError()) offlineId=sale.offlineId
